import{c as s,Q as a,j as l,m as n}from"./chunks/framework.DOi4mjdC.js";const e="/assets/%E6%8C%87%E4%BB%A4%E7%9A%84cycle%E5%8D%A0%E6%AF%94%E6%95%B0%E6%8D%AEArithmeticUtilization-csv%EF%BC%88%E6%80%A7%E8%83%BD%E6%80%BB%E8%80%97%E6%97%B6%E4%B8%BA218-1us%EF%BC%89.DmGarmP-.png",o="/assets/%E6%8C%87%E4%BB%A4%E6%B5%81%E6%B0%B4%E5%9B%BE.xm71Fwdc.png",p="/assets/zh-cn_image_0000002085555866.lZ78BztN.png",i="/assets/zh-cn_image_0000002145980193.wSx70mhH.png",u="/assets/zh-cn_image_0000002085555866.lZ78BztN.png",c="/assets/zh-cn_image_0000002085556446.cu8_E_eL.png",g="/assets/zh-cn_image_0000002121156181.DgHDXvDS.png",r="/assets/zh-cn_image_0000002085558494.Cl_84b8h.png",d="/assets/zh-cn_image_0000002121330009.Dhfi9DHf.png",v=JSON.parse('{"title":"GroupedMatmul算子性能调优案例","description":"","frontmatter":{},"headers":[{"level":1,"title":"GroupedMatmul算子性能调优案例","slug":"groupedmatmul算子性能调优案例"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/GroupedMatmul算子性能调优案例.md","filePath":"guide/算子实践参考/优秀实践/GroupedMatmul算子性能调优案例.md"}'),q={name:"guide/算子实践参考/优秀实践/GroupedMatmul算子性能调优案例.md"};function f(h,t,m,b,_,w){return a(),l("div",null,[...t[0]||(t[0]=[n(`<h1 id="groupedmatmul算子性能调优案例" tabindex="-1">GroupedMatmul算子性能调优案例 <a class="header-anchor" href="#groupedmatmul算子性能调优案例" aria-label="Permalink to &quot;GroupedMatmul算子性能调优案例&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例对分组Matmul即GroupedMatmul算子的per-token量化场景进行性能分析和优化，GroupedMatmul算子计算过程（通过python代码表达）为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>offset = 0</span></span>
<span class="line"><span>for i in range(g):</span></span>
<span class="line"><span>    mmOut = x[offset:offset + groupList[i]] * weight[i] + bias[i]</span></span>
<span class="line"><span>    y[offset:offset + groupList[i]] = Gelu(mmOut * scale[i] * pertokenScale[offset:offset + groupList[i]])</span></span>
<span class="line"><span>    offset += groupList[i]</span></span></code></pre></div><p>验证平台为Atlas A2 训练系列产品/Atlas A2 推理系列产品。</p><p>优化分析以如下算子规格为例：</p><p><strong>表 1</strong> 算子规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;input&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;shape&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;data type&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;format&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;x&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(1024,1024)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;int8&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;weight&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(8,1024,8192)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;int8&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;NZ&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;bias&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(8,8192)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;int32&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;groupList&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;8&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;int64&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;scale&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(8,8192)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;pertokenScale&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;1024&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;y&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(1024,8192)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>主要介绍以下优化方法：</p><ul><li>对于Vector计算占比较高（Vector Bound）的场景，将AI Core中的AIC核和AIV核启动比例设置为1:2；</li><li>优化CV并行流水，减少Cube和Vector计算间的空闲等待时间；</li><li>优化Vector计算流水，提高Vector并行计算速度。</li></ul><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>固定8核测试，即当前性能和后续优化tiling中numBlocks固定设置为8。</p><p>通过msProf算子调优工具获取算子性能数据：</p><ul><li>获取真实环境执行的性能数据（指令的cycle占比数据ArithmeticUtilization.csv），包含各个流水的占比情况；</li><li>获取仿真性能数据（指令流水图），包含各个流水的占用区间，可观察流水间依赖情况，从而优化并行效率。</li></ul><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><p>固定8核进行测试的情况下，通过msprof op命令获取指令的cycle占比数据如下：</p><p><strong>图 1</strong> 指令的cycle占比数据ArithmeticUtilization.csv（性能总耗时为218.1us）<br><img src="`+e+'" alt="" title="指令的cycle占比数据ArithmeticUtilization-csv（性能总耗时为218-1us）"></p><p>通过msprof op simulator获取到的指令流水图如下图所示：</p><p><strong>图 2</strong> 指令流水图<br><img src="'+o+'" alt="" title="指令流水图"></p><p>结合上述两种数据（真实数据和仿真数据）进行性能分析：</p><ul><li><p>Vector计算bound，当前为减少核启动开销设置为1:1；</p></li><li><p>实际优化过程中，对上述问题进行优化、Vector计算占比下降后，Cube和Vector计算各自都有间隙，相互之间都有等待耗时；</p><p><img src="'+p+'" alt=""></p></li><li><p>Vector计算没有开启double buffer，计算和数据搬运部分没有并行。</p><p><img src="'+i+`" alt=""></p></li></ul><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><ul><li><p>将AI Core中的AIC核和AIV核启动比例设置为1:2。每次AIC输出的数据，由两个AIV并行计算对应的反量化和激活函数；在Vector侧代码的循环里，AIV0和AIV1交替进行计算（前提条件，循环次数不为1）。代码示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t vecCount = 0;</span></span>
<span class="line"><span>uint32_t taskRation = GetTaskRatio();</span></span>
<span class="line"><span>for (uint32_t offsetN = 0; offsetN &lt; curCubeSingleN; offsetN += mnConfig.baseN) {</span></span>
<span class="line"><span>    if (unlikely(offsetN + mnConfig.baseN &gt;= curCubeSingleN)) {</span></span>
<span class="line"><span>        curVecBaseN = curCubeSingleN - offsetN;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    uint32_t alignBaseN = Ceil(curVecBaseN, uint32_t(8)) * 8;</span></span>
<span class="line"><span>    DataCopyScale(curVecBaseN, alignBaseN, scaleOffset + offsetN);</span></span>
<span class="line"><span>    uint32_t curVecBaseM = vecBaseM;</span></span>
<span class="line"><span>    uint64_t mmOutOffset = mnConfig.workSpaceOffset + offsetN * mnConfig.baseM;</span></span>
<span class="line"><span>    CrossCoreWaitFlag(SYNC_AIC_TO_AIV);</span></span>
<span class="line"><span>    for (uint32_t offsetM = 0; offsetM &lt; curCubeSingleM; offsetM += vecBaseM) {</span></span>
<span class="line"><span>         vecCount++;</span></span>
<span class="line"><span>        if (vecCount % taskRation != subBlockIdx) {</span></span>
<span class="line"><span>            continue;  // AIV0和AIV1交替进行计算</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        if (unlikely(offsetM + vecBaseM &gt;= curCubeSingleM)) { </span></span>
<span class="line"><span>            curVecBaseM = curCubeSingleM - offsetM; </span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        // 使用AscendDequant接口做perchannel反量化</span></span>
<span class="line"><span>        LocalTensor&lt;cT::T&gt; mmOutLocal = vecInQueue.AllocTensor&lt;cT::T&gt;();</span></span>
<span class="line"><span>        DataCopyPad2D(mmOutLocal, mmOutGm[mmOutOffset + offsetM * curVecBaseN],</span></span>
<span class="line"><span>                      curVecBaseM, curVecBaseN, curVecBaseN);</span></span>
<span class="line"><span>        vecInQueue.EnQue(mmOutLocal);</span></span>
<span class="line"><span>        ComputeDequantAndActivate(mnConfig, curVecBaseM, alignBaseN, curVecBaseN, offsetM);</span></span>
<span class="line"><span>        LocalTensor&lt;DTYPE_Y&gt; yLocal = vecOutQueue.DeQue&lt;DTYPE_Y&gt;();</span></span>
<span class="line"><span>        DataCopyPad2D(yGm[outOffset + offsetM * tiling-&gt;n + offsetN], yLocal,</span></span>
<span class="line"><span>                      curVecBaseM, curVecBaseN, alignBaseN, tiling-&gt;n);</span></span>
<span class="line"><span>        vecOutQueue.FreeTensor(yLocal);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>AIC和AIV启动比例设置为1:2后，出现Cube和Vector计算各自都有间隙、相互之间都有等待耗时的情况。分析原因是因为Vector和Cube计算存在使用一份workspace进行数据传递的场景，通过4份workspace的方案进行优化：host按4倍baseM * baseN申请workspace，Cube侧代码在计算前可以跳过前4轮的等待。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if ASCEND_IS_AIC {</span></span>
<span class="line"><span>    if (cubeCount &gt;= tiling-&gt;parallNum) {  // tiling-&gt;parallNum设置为4</span></span>
<span class="line"><span>        CrossCoreWaitFlag(SYNC_AIV_TO_AIC);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    mm.SetOrgShape(mnConfig.m, tiling-&gt;n, tiling-&gt;k);</span></span>
<span class="line"><span>    mm.SetSingleShape(curSingleM, curSingleN, tiling-&gt;k);</span></span>
<span class="line"><span>    mm.SetTensorA(xGm[xOffset]);</span></span>
<span class="line"><span>    auto weightSlice = weightGm[weightOffset];</span></span>
<span class="line"><span>    if (mnConfig.numBlocksM == 1) {</span></span>
<span class="line"><span>        weightSlice.SetL2CacheHint(CacheMode::CACHE_MODE_DISABLE);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    mm.SetTensorB(weightSlice);</span></span>
<span class="line"><span>    uint64_t workspaceOffset = mnConfig.workSpaceOffset;</span></span>
<span class="line"><span>    while (mm.Iterate()) {</span></span>
<span class="line"><span>        mm.GetTensorC(mmOutGm[workspaceOffset], 0, true);</span></span>
<span class="line"><span>        CrossCoreSetFlag&lt;2, PIPE_FIX&gt;(SYNC_AIC_TO_AIV);</span></span>
<span class="line"><span>        workspaceOffset += (mnConfig.baseM * mnConfig.baseN);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>cubeCount++;</span></span></code></pre></div></li><li><p>Vector计算开启double buffer，InitBuffer指定分配内存块个数为2。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pipe-&gt;InitBuffer(scaleInQueue, 2, tiling-&gt;mmTilingData.baseN * sizeof(DTYPE_SCALE));</span></span>
<span class="line"><span>pipe-&gt;InitBuffer(perTokenScaleInQueue, 2, tiling-&gt;mmTilingData.baseM * sizeof(float));</span></span>
<span class="line"><span>pipe-&gt;InitBuffer(vecInQueue, 2, tiling-&gt;ubCalSize * sizeof(cT::T));</span></span>
<span class="line"><span>pipe-&gt;InitBuffer(vecOutQueue, 2, tiling-&gt;ubCalSize * sizeof(DTYPE_Y));</span></span></code></pre></div></li></ul><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><ul><li><p>将AI Core中的AIC和AIV启动比例设置为1:2后，执行总耗时从218.1us下降为154.2us。指令流水图显示Cube计算间等待变小。</p><p><img src="`+u+'" alt=""></p></li><li><p>如上图所示，Vector计算已经不处于bound状态，但Cube和Vector计算都有间隙，未被充分利用（上述两个箭头的位置）。分析原因如下：</p><p>Vector计算在等Cube计算输出的数据，Cube侧需要等Vector计算完释放workspace以存放下一轮的计算结果，当前为了让Cube、Vector计算流水并行，workspace使用了两份空间：</p><p><img src="'+c+'" alt=""></p><p>因为Vector和Cube计算存在使用一份workspace进行数据传递的场景，存在数据依赖，所以会有等待的间隔。</p><p>可以采用4份workspace进行优化：</p><p><img src="'+g+'" alt=""></p><p>优化后，总耗时由154.2us下降为131.8us。指令流水图显示Vector、Cube计算各自间隙明显减小。</p><p><img src="'+r+'" alt=""></p></li><li><p>Vector计算开启double buffer，优化后执行总耗时从131.8us下降为128.1us。</p><p><img src="'+d+'" alt=""></p></li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><ul><li>在Vector计算为主要瓶颈点时，将AI Core中的AIC核和AIV核启动比例设置为1:2；</li><li>Cube、Vector计算时间接近，且两者都有因相互等待导致的间隙时，采用4份workspace优化；</li><li>观察数据搬运是否与计算相互掩盖，多轮计算没有数据依赖，且buffer够大时，开启double buffer，增加并行效率。</li></ul>',27)])])}const A=s(q,[["render",f]]);export{v as __pageData,A as default};
